<?php
declare(strict_types=1);
require_once __DIR__.'/sound-core.php';require_once __DIR__.'/inline-edit.php';require_once __DIR__.'/youtube-store.php';
/** Read-only inventory; repair requires a reviewed value and a current fingerprint. */
function nrq_fields():array{return ['title'=>'title','confirmedTitle'=>'title','lyricsBlock'=>'lyrics','lyrics'=>'lyrics','sunoStyle'=>'sunoPrompt','sunoPrompt'=>'sunoPrompt','sunoShareUrl'=>'sunoUrl','sunoUrl'=>'sunoUrl','youtubeUrl'=>'youtubeUrl','mvUrl'=>'mvUrl','musicVideoUrl'=>'mvUrl','thumbUrl'=>'cardImageLocation','coverImageUrl'=>'cardImageLocation','cardImageLocation'=>'cardImageLocation','audioUrl'=>'audioFileLocation','audioFileLocation'=>'audioFileLocation','vocalInfo'=>'vocal','vocal'=>'vocal','songDescription'=>'songDescription','descriptionBlock'=>'songDescription','youtubeDescription'=>'description','description'=>'description','geminiPrompt'=>'geminiPrompt','youtubeTitle'=>'youtubeTitle','communityPost'=>'communityPost','fanLetter'=>'communityPost','lyricsTranslation'=>'lyricsTranslation','productionPrompt'=>'productionPrompt','characterPrompt'=>'characterPrompt'];}
function nrq_aliases():array{return ['sunoPrompt'=>['sunoPrompt','sunoStyle'],'sunoUrl'=>['sunoUrl','sunoShareUrl'],'communityPost'=>['communityPost','fanLetter'],'cardImageLocation'=>['cardImageLocation','coverImageUrl','thumbUrl'],'audioFileLocation'=>['audioFileLocation','audioUrl'],'mvUrl'=>['mvUrl','musicVideoUrl'],'vocal'=>['vocalInfo','vocal']];}
function nrq_source_label(string $key):string{return ['sunoPrompt'=>'현재 곡정보','sunoStyle'=>'이전 제작 양식','sunoUrl'=>'현재 공유 주소','sunoShareUrl'=>'이전 공유 주소','communityPost'=>'현재 게시 정보','fanLetter'=>'이전 커뮤니티 글','cardImageLocation'=>'현재 카드 이미지','coverImageUrl'=>'이전 커버 이미지','thumbUrl'=>'이전 썸네일','audioFileLocation'=>'현재 음원 위치','audioUrl'=>'이전 음원 주소','mvUrl'=>'현재 뮤직비디오','musicVideoUrl'=>'이전 뮤직비디오','vocalInfo'=>'현재 보컬 정보','vocal'=>'이전 보컬 정보'][$key]??$key;}
function nrq_issue(array $issue):array{$issue['fingerprint']=hash('sha256',json_encode($issue,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return $issue;}
function nrq_scan(PDO $db):array{
 $rows=$db->query("SELECT doc_key,kind,payload,revision FROM noa_documents WHERE kind IN ('single','story','playlist') ORDER BY doc_key LIMIT 20001")->fetchAll(PDO::FETCH_ASSOC);if(count($rows)>20000)throw new DomainException('scan_limit');
 $docs=[];$issues=[];$media=[];
 foreach($rows as $row){$d=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);if(!is_array($d)||!empty($d['_noaTrash']))continue;$key=$row['doc_key'];$docs[$key]=$row+['document'=>$d];$f=nup_fields($d);$base=['key'=>$key,'title'=>$f['title']?:$key,'revision'=>(int)$row['revision'],'editUrl'=>'/noa-editor.php?key='.rawurlencode($key)];
  foreach(nrq_aliases() as $field=>$aliases){$choices=[];foreach($aliases as $alias)if(isset($d['body'][$alias])&&is_string($d['body'][$alias])){$v=$d['body'][$alias];$i=array_search($v,array_column($choices,'value'),true);if($i===false)$choices[]=['value'=>$v,'sources'=>[nrq_source_label($alias)]];else $choices[$i]['sources'][]=nrq_source_label($alias);}if(count($choices)>1)$issues[]=nrq_issue($base+['id'=>'alias:'.hash('sha256',$key.':'.$field),'type'=>'alias','field'=>$field,'message'=>'같은 항목의 저장 값이 서로 다릅니다.','choices'=>$choices,'canResolve'=>true]);}
  if(trim($f['title'])==='')$issues[]=nrq_issue($base+['id'=>'title:'.hash('sha256',$key),'type'=>'missing','field'=>'title','message'=>'곡 제목이 비어 있습니다.','canResolve'=>false]);
  if(!in_array($d['genreId']??'',NUP_GENRES,true)&&!(($d['genreId']??'')==='unclassified'&&($d['classificationOverride']['source']??'')==='manual'))$issues[]=nrq_issue($base+['id'=>'genre:'.hash('sha256',$key),'type'=>'classification','field'=>'genre','message'=>'등록 장르와 공통 분류 기준의 연결을 확인해 주세요.','actionUrl'=>'/noa-editor.php?key='.rawurlencode($key),'actionLabel'=>'곡 분류 수정','canResolve'=>false]);
  if($row['kind']!=='playlist')foreach(['sunoUrl','youtubeUrl','audioFileLocation'] as $field)if(trim($f[$field])!==''){$url=trim($f[$field]);if($field==='youtubeUrl'&&($video=ny_video_id($url)))$url='https://www.youtube.com/watch?v='.$video;$media[$field.'|'.$url][]=$base;}
 }
 $batch=$db->query("SELECT batch_id FROM noa_catalog_batches WHERE status='applied' ORDER BY applied_at DESC,batch_id DESC LIMIT 1")->fetchColumn();$aliases=[];
 if($batch){$sourceNames=[];$q=$db->prepare('SELECT s.source_id,s.source_path FROM noa_catalog_sources s JOIN noa_catalog_batch_sources b ON b.source_id=s.source_id WHERE b.batch_id=?');$q->execute([$batch]);foreach($q as $s)$sourceNames[$s['source_id']]=$s['source_path'];$q=$db->prepare('SELECT alias_key,entity_id FROM noa_catalog_aliases WHERE batch_id=?');$q->execute([$batch]);foreach($q as $a)$aliases[$a['alias_key']][]=$a['entity_id'];
  $q=$db->prepare("SELECT * FROM noa_catalog_conflicts WHERE batch_id=? AND status<>'resolved' ORDER BY conflict_id");$q->execute([$batch]);foreach($q as $c){$field=nrq_fields()[$c['field_name']]??null;$choices=[];foreach(json_decode($c['alternatives'],true,512,JSON_THROW_ON_ERROR) as $i=>$option){$v=$option['value']??$option;if(!is_string($v))continue;$found=array_search($v,array_column($choices,'value'),true);$source='원본 대안 '.($i+1);if(is_array($option)&&!empty($option['sources'])){$paths=[];foreach(array_keys($option['sources']) as $sourceId)if(isset($sourceNames[$sourceId]))$paths[]=$sourceNames[$sourceId];if($paths)$source.=' · '.implode(', ',array_unique($paths));}if($found===false)$choices[]=['value'=>$v,'sources'=>[$source]];else $choices[$found]['sources'][]=$source;}
   $target=null;$problem=null;try{$target=nie_resolve($db,['type'=>'song','source'=>'music','key'=>'catalog:'.$c['entity_id']]);if(!empty($target['payload']['_noaTrash']))continue;}catch(DomainException $e){$problem=$e->getMessage();}
   if($target&&$field){$current=$target['fields'][$field]??null;if(is_string($current)&&array_search($current,array_column($choices,'value'),true)===false)$choices[]=['value'=>$current,'sources'=>['현재 저장 값']];}
   $key=$target['writeKey']??'catalog:'.$c['entity_id'];$issues[]=nrq_issue(['id'=>'catalog:'.$c['conflict_id'],'type'=>'catalog','batch'=>$batch,'conflictId'=>$c['conflict_id'],'key'=>$key,'title'=>$target['fields']['title']??substr($c['entity_id'],0,12),'revision'=>$target['revision']??0,'field'=>$field??$c['field_name'],'message'=>$problem?'원본 연결을 먼저 확인해야 값을 확정할 수 있습니다.':'수집한 원본 사이에 값 충돌이 있습니다.','choices'=>$choices,'canResolve'=>$target!==null&&$field!==null&&count($choices)>0,'editUrl'=>$target?'/noa-editor.php?key='.rawurlencode($key):'/noa-app/taxonomy/']);
  }
 }
 foreach($media as $signature=>$records)if(count($records)>1){[$field,$url]=explode('|',$signature,2);$identities=[];foreach($records as &$record){$ids=$aliases[$record['key']]??[preg_replace('/^catalog:/','',$record['key'])];$record['identity']=count($ids)===1?$ids[0]:null;$identities[]=$record['identity'];}unset($record);$independent=count(array_unique($identities))===count($records)&&!in_array(null,$identities,true);$issues[]=nrq_issue(['id'=>'duplicate:'.hash('sha256',$signature),'type'=>'duplicate','field'=>$field,'title'=>$records[0]['title'],'message'=>$independent?'같은 미디어를 연결한 곡입니다. 버전·가사를 비교한 뒤 불필요한 곡만 휴지통으로 이동하세요.':'같은 통합 원본에 연결된 기록입니다. 삭제 전에 원본 연결을 검토하세요.','records'=>$records,'value'=>$url,'canTrash'=>$independent,'canResolve'=>false]);}
 return ['ok'=>true,'checkedAt'=>gmdate('c'),'scanned'=>count($docs),'counts'=>array_count_values(array_column($issues,'type')),'issues'=>$issues,'databaseWrites'=>0];
}
function nrq_resolve(PDO $db,array $request,string $actor):array{
 $id=$request['issueId']??null;$fingerprint=$request['fingerprint']??null;$choice=$request['choice']??null;$requestId=$request['requestId']??'';
 if(!is_string($id)||!is_string($fingerprint)||!preg_match('/^[a-f0-9]{64}$/D',$fingerprint)||!is_int($choice)||$choice<0||!is_string($requestId)||!preg_match('/^[a-f0-9-]{36}$/iD',$requestId))throw new InvalidArgumentException('invalid_resolution');
 $hash=hash('sha256',json_encode([$id,$fingerprint,$choice],JSON_THROW_ON_ERROR));$db->beginTransaction();try{
  $q=$db->prepare('SELECT doc_key,request_hash,revision FROM noa_request_log WHERE request_id=? FOR UPDATE');$q->execute([$requestId]);$retry=$q->fetch(PDO::FETCH_ASSOC);if($retry){if(!hash_equals($retry['request_hash'],$hash))throw new DomainException('idempotency_reuse');$db->commit();return ['ok'=>true,'key'=>$retry['doc_key'],'revision'=>(int)$retry['revision'],'replayed'=>true];}
  // Serialize reviewed metadata with ordinary editors and catalog publication.
  $db->query("SELECT doc_key FROM noa_documents WHERE kind IN ('single','story','playlist') ORDER BY doc_key FOR UPDATE")->fetchAll();$db->query('SELECT batch_id FROM noa_catalog_batches ORDER BY batch_id FOR UPDATE')->fetchAll();$db->query('SELECT conflict_id FROM noa_catalog_conflicts ORDER BY batch_id,conflict_id FOR UPDATE')->fetchAll();
  $issue=null;foreach(nrq_scan($db)['issues'] as $candidate)if($candidate['id']===$id){$issue=$candidate;break;}
  if(!$issue||!$issue['canResolve']||!hash_equals($issue['fingerprint'],$fingerprint))throw new DomainException('review_changed');if(!isset($issue['choices'][$choice]))throw new InvalidArgumentException('invalid_choice');
  $r=nie_resolve($db,['type'=>'song','source'=>'music','key'=>$issue['key']]);if($r['revision']!==$issue['revision']||!empty($r['payload']['_noaTrash']))throw new DomainException('review_changed');$value=$issue['choices'][$choice]['value'];$payload=nup_patch($r['payload'],$r['kind'],[$issue['field']=>$value]);$next=nup_store($db,$r['writeKey'],$r['kind'],$payload,$r['revision'],$actor);
  if($issue['type']==='catalog'){$q=$db->prepare("UPDATE noa_catalog_conflicts SET status='resolved',resolution=?,resolved_by=?,resolved_at=CURRENT_TIMESTAMP WHERE batch_id=? AND conflict_id=? AND status<>'resolved'");$q->execute([json_encode(['key'=>$r['writeKey'],'revision'=>$next,'field'=>$issue['field'],'value'=>$value,'fingerprint'=>$fingerprint],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$actor,$issue['batch'],$issue['conflictId']]);if($q->rowCount()!==1)throw new DomainException('review_changed');}
  $q=$db->prepare('INSERT INTO noa_request_log(request_id,doc_key,request_hash,revision) VALUES(?,?,?,?)');$q->execute([$requestId,$r['writeKey'],$hash,$next]);$db->commit();return ['ok'=>true,'key'=>$r['writeKey'],'revision'=>$next,'replayed'=>false];
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
